import * as THREE from '/vendor/three.module.js';
import {createStormAudio} from '/audio.js';
export function createSimulator(host,type){
 const winter=['blizzard','ice'].includes(type),sea=type==='hurricane',dust=type==='dust';
 const scene=new THREE.Scene();scene.background=new THREE.Color(dust?'#29241f':'#101d2b');scene.fog=new THREE.FogExp2(dust?0x29241f:0x101d2b,.022);
 const camera=new THREE.PerspectiveCamera(43,1,.1,180),renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setSize(host.clientWidth,host.clientHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;host.appendChild(renderer.domElement);const canvas=renderer.domElement;canvas.tabIndex=0;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','הדמיה תלת־ממדית אינטראקטיבית. מקשי חצים לסיבוב, פלוס ומינוס להתקרבות ולהתרחקות.');
 scene.add(new THREE.HemisphereLight(0xc8e4ff,0x263239,2.5));const light=new THREE.DirectionalLight(0xe5f6ff,2);light.position.set(10,20,8);scene.add(light);
 const materials=[],geometries=[];function mat(color,opts={}){const m=new THREE.MeshStandardMaterial({color,roughness:.8,...opts});materials.push(m);return m;}function mesh(geo,m,x=0,y=0,z=0,parent=scene){geometries.push(geo);const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);parent.add(o);return o;}
 const ground=mesh(new THREE.CylinderGeometry(14,14,1,80),mat(sea?0x174658:winter?0x9aacb6:dust?0x9a7750:0x3b514b),0,-.65,0);const ring=mesh(new THREE.TorusGeometry(14.1,.035,6,100),mat(0x72959b,{emissive:0x244047}),0,-.1,0);ring.rotation.x=Math.PI/2;
 const grid=new THREE.GridHelper(27,18,0x7d9aa5,0x7d9aa5);grid.position.y=-.12;grid.material.transparent=true;grid.material.opacity=.12;scene.add(grid);
 let rng=127;function rand(){rng=(rng*16807)%2147483647;return(rng-1)/2147483646;}
 const wood=mat(0x574e45),green=mat(winter?0x53706d:0x324e46),snow=mat(0xdce9ee);const coats=[];
 function branch(a,b,r,m){const v=new THREE.Vector3().subVectors(b,a),o=mesh(new THREE.CylinderGeometry(r*.65,r,v.length(),8),m);o.position.copy(a).add(b).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v.normalize());return o;}
 function tree(x,z,h){mesh(new THREE.CylinderGeometry(.1,.19,h,7),wood,x,h/2,z);for(let j=0;j<3;j++)mesh(new THREE.ConeGeometry(h*.34*(1-j*.18),h*.65,9),j===2&&winter?snow:green,x,h*.5+j*h*.2,z);}
 if(!sea){if(type==='ice'){const iceMat=mat(0xb6e5f8,{transparent:true,opacity:.58,metalness:.15,roughness:.12});const a=new THREE.Vector3(0,0,0),b=new THREE.Vector3(0,6,0);branch(a,b,.28,wood);coats.push(branch(a,b,.33,iceMat));for(let i=0;i<14;i++){const y=1.5+i*.28,t=i*2.4,base=new THREE.Vector3(0,y,0),end=new THREE.Vector3(Math.cos(t)*(2.9-y*.2),y+1.2,Math.sin(t)*(2.9-y*.2));branch(base,end,.085,wood);coats.push(branch(base,end,.115,iceMat));const tip=end.clone().add(new THREE.Vector3(.2,.7,.3));branch(end,tip,.045,wood);coats.push(branch(end,tip,.07,iceMat));mesh(new THREE.ConeGeometry(.07,.55,6),iceMat,end.x,end.y-.2,end.z).rotation.z=Math.PI;}}else{for(let i=0;i<(dust?0:19);i++){const t=rand()*Math.PI*2,r=8+rand()*4;tree(Math.cos(t)*r,Math.sin(t)*r,1.3+rand()*1.6);}for(let i=0;i<10;i++){const t=rand()*Math.PI*2,r=10+rand()*2;const hill=mesh(new THREE.IcosahedronGeometry(1,1),mat(dust?0x99754d:winter?0xa8b7bd:0x425c52),Math.cos(t)*r,.1,Math.sin(t)*r);hill.scale.set(1+rand()*1.8,.5+rand(),1+rand());}}}
 const cloudMat=mat(0x9caebf,{transparent:true,opacity:.72,roughness:1});const clouds=new THREE.Group();scene.add(clouds);if(!sea&&!dust&&type!=='blizzard'&&type!=='ice'){const cloudGeo=new THREE.SphereGeometry(1,12,8);geometries.push(cloudGeo);for(let i=0;i<24;i++){const o=new THREE.Mesh(cloudGeo,cloudMat);o.position.set((rand()-.5)*10,8+rand()*1.5,(rand()-.5)*6);o.scale.set(1.5+rand(),.55+rand()*.5,1.3+rand());clouds.add(o);}}
 const N=sea?4200:type==='tornado'?3200:1800,positions=new Float32Array(N*3),seeds=new Float32Array(N*4);for(let i=0;i<N*4;i++)seeds[i]=rand();const pg=new THREE.BufferGeometry();pg.setAttribute('position',new THREE.BufferAttribute(positions,3));geometries.push(pg);
 const particleMaterial=new THREE.ShaderMaterial({transparent:true,depthWrite:false,uniforms:{uColor:{value:new THREE.Color(dust?0xd9ae77:sea?0xd2e3ec:0xd9e9f4)},uSize:{value:sea?39:type==='tornado'?24:dust?16:type==='hail'?10:type==='blizzard'?7:3},uOpacity:{value:sea?.55:type==='tornado'?.4:dust?.3:.8}},vertexShader:'uniform float uSize; void main(){ vec4 mv=modelViewMatrix*vec4(position,1.0); gl_PointSize=clamp(uSize*14.0/-mv.z,1.0,60.0); gl_Position=projectionMatrix*mv; }',fragmentShader:'uniform vec3 uColor; uniform float uOpacity; void main(){ float d=length(gl_PointCoord-0.5)*2.0; if(d>1.0) discard; gl_FragColor=vec4(uColor, uOpacity*pow(1.0-d,1.5)); }'});materials.push(particleMaterial);const points=new THREE.Points(pg,particleMaterial);points.frustumCulled=false;scene.add(points);
 let bolt;if(type==='thunderstorm'){const pts=[new THREE.Vector3(.5,8,0),new THREE.Vector3(-.5,6.7,0),new THREE.Vector3(.3,5.8,0),new THREE.Vector3(-.7,4.2,0),new THREE.Vector3(0,4.2,0),new THREE.Vector3(-1.5,.1,0)];const bg=new THREE.BufferGeometry().setFromPoints(pts);geometries.push(bg);const bm=new THREE.LineBasicMaterial({color:0xd7caff});materials.push(bm);bolt=new THREE.Line(bg,bm);scene.add(bolt);}
 let t=0,intensity=.5,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,az=.6,el=sea?1.12:.47,distance=sea?35:31,active=true,last=0,raf=null,disposed=false;
 function requestRender(){if(!disposed&&active&&!document.hidden&&raf===null)raf=requestAnimationFrame(draw);}
 function stopFrames(){if(raf!==null)cancelAnimationFrame(raf);raf=null;last=0;}
 const audio=createStormAudio(type);
 const pause=document.getElementById('pause'),slider=document.getElementById('intensity'),output=document.getElementById('intensity-value');function syncPause(){audio.update(paused,intensity,active);pause.textContent=paused?'הפעלת הסופה':'השהיית הסופה';pause.setAttribute('aria-pressed',String(paused));stopFrames();requestRender();}syncPause();pause.onclick=()=>{paused=!paused;syncPause();};slider.oninput=()=>{intensity=Number(slider.value)/100;output.value=slider.value+'%';audio.update(paused,intensity,active);requestRender();};function reset(){t=0;intensity=.5;slider.value='50';output.value='50%';az=.6;el=sea?1.12:.47;distance=sea?35:31;paused=matchMedia('(prefers-reduced-motion: reduce)').matches;syncPause();}document.getElementById('reset').onclick=reset;
 const zoom=d=>{distance=Math.max(18,Math.min(60,distance+d));requestRender();};document.getElementById('zoom-in').onclick=()=>zoom(-3);document.getElementById('zoom-out').onclick=()=>zoom(3);
 const fingers=new Map();let pinch=0;canvas.onpointerdown=e=>{fingers.set(e.pointerId,[e.clientX,e.clientY]);canvas.setPointerCapture(e.pointerId);pinch=0;};canvas.onpointermove=e=>{if(!fingers.has(e.pointerId))return;const old=fingers.get(e.pointerId);fingers.set(e.pointerId,[e.clientX,e.clientY]);if(fingers.size===2){const [a,b]=[...fingers.values()],d=Math.hypot(a[0]-b[0],a[1]-b[1]);if(pinch)zoom((pinch-d)*.07);pinch=d;}else{az-=(e.clientX-old[0])*.008;el=Math.max(.12,Math.min(1.45,el+(e.clientY-old[1])*.006));}requestRender();};const up=e=>{fingers.delete(e.pointerId);pinch=0;};canvas.onpointerup=up;canvas.onpointercancel=up;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY*.025);},{passive:false});canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')az-=.12;if(e.key==='ArrowRight')az+=.12;if(e.key==='ArrowUp')el=Math.min(1.45,el+.1);if(e.key==='ArrowDown')el=Math.max(.12,el-.1);if(e.key==='+'||e.key==='=')zoom(-2);if(e.key==='-')zoom(2);requestRender();}};
 const resize=new ResizeObserver(()=>{camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();renderer.setSize(host.clientWidth,host.clientHeight);requestRender();});resize.observe(host);const visibility=new IntersectionObserver(([entry])=>{active=entry.isIntersecting;audio.update(paused,intensity,active);stopFrames();requestRender();});visibility.observe(host);
 const pageVisibility=()=>{stopFrames();requestRender();};document.addEventListener("visibilitychange",pageVisibility);
 function draw(now){raf=null;if(disposed||!active||document.hidden){last=0;return;}const dt=last?Math.min((now-last)/1000,.04):0;last=now;if(!paused)t+=dt*(.35+intensity*1.1);for(let i=0;i<N;i++){const a=seeds[i*4],b=seeds[i*4+1],c=seeds[i*4+2],d=seeds[i*4+3];let x,y,z;if(sea){const r=1.7+Math.pow(a,.8)*10,angle=Math.floor(b*5)*Math.PI*2/5+Math.log(r)*2.6+(c-.5)*.55+t*.2;x=Math.cos(angle)*r;z=-Math.sin(angle)*r;const arm=Math.pow((Math.sin(b*Math.PI*10)+1)/2,3);y=.9+c*1.3+arm*.8; }else if(type==='tornado'){y=a*8.3;const r=(.22+Math.pow(a,2)*3.6)*(.7+intensity*.6)*(.7+c*.4),angle=b*Math.PI*2+t*(3-a*1.7);x=Math.cos(angle)*r+Math.sin(a*2)*.45;z=Math.sin(angle)*r; }else if(dust){x=((a*28+t*3)%28)-14;y=b*6*(.4+intensity*.6);z=(c-.5)*22;}else{const fall=type==='hail'?5:type==='blizzard'?1.7:6;y=10-((a*10+t*fall)%10);x=(b-.5)*23+(type==='blizzard'?Math.sin(t+c*4)*1.4+(10-y)*intensity*.55:(10-y)*.08);z=(c-.5)*22;if(type==='hail'&&y<.4)y=.15+Math.abs(Math.sin((t+d)*9))*.35; }positions[i*3]=x;positions[i*3+1]=y;positions[i*3+2]=z;}
 pg.attributes.position.needsUpdate=true;if(['blizzard','dust'].includes(type))pg.setDrawRange(0,Math.floor(N*(.25+intensity*.75)));if(type==='hail')particleMaterial.uniforms.uSize.value=6+intensity*14;coats.forEach(o=>{o.scale.x=o.scale.z=1+intensity*.7;});if(bolt)bolt.rotation.y=Math.sin(t*.3)*.3;
 const targetY=sea?0:3;camera.position.set(Math.sin(az)*Math.cos(el)*distance,targetY+Math.sin(el)*distance,Math.cos(az)*Math.cos(el)*distance);camera.lookAt(0,targetY,0);renderer.render(scene,camera);if(!paused)requestRender();}
 requestRender();return()=>{disposed=true;audio.destroy();stopFrames();document.removeEventListener("visibilitychange",pageVisibility);resize.disconnect();visibility.disconnect();geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());grid.geometry.dispose();grid.material.dispose();renderer.dispose();canvas.remove();};
}
